.selectable-tile {
  position: relative;
  display: grid;
  /* glyph · words · mark. The mark sits with the name it answers, not in a far
   * corner, and the detail lines indent under the name like an option row in
   * any list of choices. The old layout put the glyph on a line of its own and
   * spread four short lines over 130px, which is a tile with nothing in it. */
  grid-template-columns: auto minmax(0, 1fr) auto;
  align-items: center;
  gap: var(--space-1) var(--space-3);
  padding: var(--space-4);
  border: var(--surface-edge);
  border-radius: var(--card-radius);
  background: var(--card);
  color: var(--card-foreground);
  cursor: pointer;
  transition: border-color var(--duration-fast);
}
.selectable-tile:hover { border-color: var(--border-strong, var(--border)); }
/* Pressed: one stop past hover, the third answer every control now gives. */
.selectable-tile:active:not([data-disabled]) { background: var(--surface-hover); }
.selectable-tile[data-disabled] { opacity: var(--disabled-opacity); cursor: not-allowed; }

/* The real control, kept in the DOM so the keyboard, the radio group and the
 * form all work, and visually replaced by the mark. */
.selectable-tile-input {
  position: absolute;
  inline-size: 1px;
  block-size: 1px;
  opacity: 0;
  margin: 0;
}

/* THE MARK IS THE SYSTEM'S RADIO AND CHECKBOX, TO THE PIXEL.
 *
 * It was a filled primary circle with a white dot — the inverse of what <Radio>
 * draws, so a tile and a radio in the same form disagreed about what "chosen"
 * looks like (owner, 23.08: make sure this is our radio button). These are the
 * values from Radio.css and Checkbox.css: 1.5px --border-strong on --background,
 * the accent border when checked, a 50% dot in --primary for the single choice
 * and the tick in --primary-foreground on --primary for the multiple one. If
 * those files move, this moves with them. */
.selectable-tile-mark {
  grid-column: 3;
  grid-row: 1;
  position: relative;
  display: inline-grid;
  place-items: center;
  inline-size: 1.25rem;
  block-size: 1.25rem;
  border: 1.5px solid var(--border-strong, var(--border));
  border-radius: var(--radius-full);
  background: var(--background);
  color: var(--primary-foreground);
  transition: background var(--duration-fast), border-color var(--duration-fast);
}
.selectable-tile[data-multiple] .selectable-tile-mark { border-radius: var(--radius-sm); }
.selectable-tile-mark .icon { opacity: 0; }

/* Chosen is a BORDER and a mark, not a fill (owner, 23.08). A tinted tile reads
 * as a disabled or a highlighted surface, and in a set of them the colour is
 * the loudest thing on the screen while the actual answer — which one is
 * ticked — is the smallest. */
.selectable-tile[data-selected] { border-color: var(--primary); }
.selectable-tile[data-selected] .selectable-tile-mark { border-color: var(--primary-accent); }
/* Multiple: the box fills and the tick shows, exactly as <Checkbox> does. */
.selectable-tile[data-selected][data-multiple] .selectable-tile-mark {
  background: var(--primary);
  border-color: var(--primary);
}
.selectable-tile[data-selected][data-multiple] .selectable-tile-mark .icon { opacity: 1; }
/* Single: a 50% dot in the middle, exactly as <Radio> does — a tick would
   promise it can be un-ticked. */
.selectable-tile[data-selected]:not([data-multiple]) .selectable-tile-mark::after {
  content: "";
  position: absolute;
  inset: 0;
  margin: auto;
  inline-size: 50%;
  block-size: 50%;
  border-radius: var(--radius-full);
  background: var(--primary);
}

.selectable-tile:has(.selectable-tile-input:focus-visible) {
  outline: var(--focus-ring);
  outline-offset: var(--ring-offset);
}

.selectable-tile-icon { grid-column: 1; grid-row: 1; color: var(--muted-foreground); }
.selectable-tile[data-selected] .selectable-tile-icon { color: var(--primary-accent); }
.selectable-tile-title { grid-column: 2; grid-row: 1; font-weight: var(--font-weight-medium); }
.selectable-tile-description { grid-column: 2 / -1; font-size: var(--font-sm); color: var(--muted-foreground); }
.selectable-tile-meta {
  grid-column: 2 / -1;
  font-size: var(--font-sm);
  color: var(--muted-foreground);
  font-variant-numeric: tabular-nums;
}

import "./SelectableTile.css";
import type { ReactNode } from "react";
import { cn } from "../lib/cn";
import { Icon, type IconName } from "../Icon";

type Props = {
  /** What this option is. */
  title: ReactNode;
  /** Whether it is currently chosen — this is a controlled control. */
  selected: boolean;
  /** Called with what the state becomes. */
  onSelect: (selected: boolean) => void;
  /** true when several tiles can be chosen at once: a checkbox mark instead of
   *  a radio one, and no group name needed. */
  multiple?: boolean;
  /** The group this tile belongs to. Required for a single-choice set — it is
   *  what makes the browser treat the tiles as one radio group (arrow keys,
   *  one choice, form submission). */
  name?: string;
  /** Icon name, above the title. */
  icon?: IconName;
  /** One line: what choosing this one means. */
  description?: ReactNode;
  /** Trailing facts — a price, a region, a size. */
  meta?: ReactNode;
  /** Dimmed and unpressable, but pointer events are KEPT so a Tooltip can say why this option is
   *  not available.
   */
  disabled?: boolean;
  className?: string;
};

/** A card that IS the control: the whole surface picks the option it shows,
 *  over a real radio or checkbox so the keyboard and the form get it for free.
 *  Reach for <LinkTile> when the tile navigates instead, for <Radio> or
 *  <Checkbox> when the options are words, and for <PlanCard> when the option is
 *  a priced plan. 
 *
 * Copy: the title is the choice, the description is what picking it means for
 * the reader — not a feature list. Options in one set stay parallel.
 */
export function SelectableTile({
  title,
  selected,
  onSelect,
  multiple,
  name,
  icon,
  description,
  meta,
  disabled,
  className,
}: Props) {
  return (
    <label
      className={cn("selectable-tile", className)}
      data-selected={selected ? "" : undefined}
      data-multiple={multiple ? "" : undefined}
      data-disabled={disabled ? "" : undefined}
    >
      <input
        className="selectable-tile-input"
        type={multiple ? "checkbox" : "radio"}
        name={name}
        checked={selected}
        disabled={disabled}
        onChange={(e) => onSelect(e.target.checked)}
      />
      <span className="selectable-tile-mark" aria-hidden="true">
        {multiple && <Icon name="check" size="sm" />}
      </span>
      {icon && (
        <span className="selectable-tile-icon" aria-hidden="true">
          <Icon name={icon} size="md" />
        </span>
      )}
      <span className="selectable-tile-title">{title}</span>
      {description && <span className="selectable-tile-description">{description}</span>}
      {meta && <span className="selectable-tile-meta">{meta}</span>}
    </label>
  );
}
